@block RotaryCtrl begin
    # 1 kHz firmware of the rotary pendulum (generated by design/build_model.py from design.json).
    #
    #   phase 0  t < t_on            motor voltage 0 (hanging, at rest)
    #   phase 1  swing-up            u = u*(t) - K(t) (x - x*(t)),  the TVLQR table `Tab` (rows every dt_tab)
    #   phase 2  balance (latched)   u = -Klqr x,  the infinite-horizon LQR at the upright
    #
    # x = [q1 .. q_n, w1 .. w_n]: the joint coordinates and rates of the bond graph (arm angle, first link
    # from upright, then every link relative to the one below). A table row is
    # [x*_1 .. x*_2n, u*, K_1 .. K_2n]; the row is picked by linear interpolation (hat functions) at
    # (tm - t_on)/dt_tab. The switch to phase 2 happens once, when tm - t_on >= t_s and the weighted
    # norm sqrt(sum cw_i x_i^2) is below catch_tol; the voltage is clamped to +-umax. The sampling
    # (zero-order hold) breaks the algebraic loop through the plant.
    @constants NT::Int = 401
    @inputs begin
        q1::Real
        q2::Real
        q3::Real
        w1::Real
        w2::Real
        w3::Real
        tm::Real
    end
    @outputs begin
        u::Real = 0.0, [unit = "V"]
        phase::Real = 0.0
        enorm::Real = 0.0
    end
