        end
        utv = c7 - (c8 * (q1 - c1) + c9 * (q2 - c2) + c10 * (q3 - c3) + c11 * (w1 - c4) + c12 * (w2 - c5) + c13 * (w3 - c6))
        ulq = -(Klqr[1] * q1 + Klqr[2] * q2 + Klqr[3] * q3 + Klqr[4] * w1 + Klqr[5] * w2 + Klqr[6] * w3)
        en = sqrt(cw[1] * q1 * q1 + cw[2] * q2 * q2 + cw[3] * q3 * q3 + cw[4] * w1 * w1 + cw[5] * w2 * w2 + cw[6] * w3 * w3)
        lat = ifelse(latched > 0.5 || (tau >= t_s && en < catch_tol), 1.0, 0.0)
        latched = lat
        u = clamp(ifelse(tm < t_on, 0.0, ifelse(lat > 0.5, ulq, utv)), -umax, umax)
        phase = ifelse(tm < t_on, 0.0, ifelse(lat > 0.5, 2.0, 1.0))
        enorm = en
    end
end
